<template x-if="find(selected)?.type==='dropdown-menu'"><div><label class="ff-source-field"><span>{{ __('filaforge::studio.menu_brand') }}</span><input type="text" maxlength="200" :value="find(selected).props.brand" x-on:change="setMenu('brand',$event.target.value)"></label><label class="ff-source-field"><span>{{ __('filaforge::studio.menu_toggle') }}</span><input type="text" maxlength="200" :value="find(selected).props.toggle" x-on:change="setMenu('toggle',$event.target.value)"></label><label class="ff-source-field"><span>{{ __('filaforge::studio.menu_collapse_at') }}</span><select :value="find(selected).props.collapseAt||'tablet'" x-on:change="setMenu('collapseAt',$event.target.value)"><option value="tablet">{{ __('filaforge::studio.menu_collapse_tablet') }}</option><option value="mobile">{{ __('filaforge::studio.menu_collapse_mobile') }}</option><option value="never">{{ __('filaforge::studio.menu_collapse_never') }}</option></select></label><button type="button" class="ff-btn ff-picker-launch" x-on:click="addMenuItem()" :disabled="find(selected).children.length>=30">{{ __('filaforge::studio.menu_add') }}</button><template x-for="item in find(selected).children" :key="item.id"><button type="button" class="ff-picker-option" x-on:click="select(item.id)" x-text="item.props.label"></button></template></div></template>
<template x-if="find(selected)?.type==='menu-item'"><div><label class="ff-source-field"><span>{{ __('filaforge::studio.menu_label') }}</span><input type="text" maxlength="200" :value="find(selected).props.label" x-on:change="setMenu('label',$event.target.value)"></label><label class="ff-source-field"><span>{{ __('filaforge::studio.menu_url') }}</span><input type="text" dir="ltr" maxlength="2048" :value="find(selected).props.url" x-on:change="setMenu('url',$event.target.value)"></label><button type="button" class="ff-btn ff-picker-launch" x-on:click="addMenuItem()">{{ __('filaforge::studio.menu_add') }}</button><button type="button" class="ff-btn ff-picker-launch" x-on:click="addMenuItem(true)">{{ __('filaforge::studio.menu_add_child') }}</button><template x-for="item in find(selected).children" :key="item.id"><button type="button" class="ff-picker-option" x-on:click="select(item.id)" x-text="item.props.label"></button></template></div></template>

<template x-if="['dropdown-menu','menu-item'].includes(find(selected)?.type)"><div class="ff-data-group">
<p class="ff-muted">{{ __('filaforge::studio.menu_responsive_hint') }}</p>
<label class="ff-source-field"><span>{{ __('filaforge::studio.menu_gap') }}</span><input type="number" min="0" max="48" placeholder="12" :value="find(selected)?.responsive?.[device]?.menuGap??''" x-on:change="setNodeResponsive('menuGap',$event.target.value===''?null:Math.max(0,Math.min(48,Number($event.target.value))))"></label>
<label class="ff-source-field"><span>{{ __('filaforge::studio.menu_submenu_width') }}</span><input type="number" min="140" max="600" placeholder="240" :value="find(selected)?.responsive?.[device]?.submenuWidth??''" x-on:change="setNodeResponsive('submenuWidth',$event.target.value===''?null:Math.max(140,Math.min(600,Number($event.target.value))))"></label>
<label class="ff-source-field"><span>{{ __('filaforge::studio.menu_submenu_indent') }}</span><input type="number" min="0" max="32" placeholder="12" :value="find(selected)?.responsive?.[device]?.submenuIndent??''" x-on:change="setNodeResponsive('submenuIndent',$event.target.value===''?null:Math.max(0,Math.min(32,Number($event.target.value))))"></label>
</div></template>
